use std::fs
use std::env
use std::process

fn emit(text: string, number: bool, n: int) -> int {
    let mut count = n
    if !number {
        print(text)
        return count
    }
    let parts: Vec<string> = text.split("\n").collect()
    let total: int = parts.len() as int
    let mut i: int = 0
    for p in parts {
        let last = i == total - 1
        i += 1
        if last && p == "" {
            continue
        }
        count += 1
        println("${count:>6}\t${p}")
    }
    return count
}

fn main() {
    let mut number = false
    let mut names: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            names.push(a)
        }
    }
    let mut count: int = 0
    let mut status: int = 0
    if names.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        count = emit(text, number, count)
    } else {
        for name in names {
            match fs::read_to_string(name) {
                Ok(t) => { count = emit(t, number, count) }
                Err(_) => {
                    println("cat: ${name}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(status)
    }
}
